<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$id=(int)($_GET['id']??0);$userId=(int)current_user()['user_id'];$st=$pdo->prepare('SELECT a.*,j.role_name,j.job_role_id FROM assessments a JOIN job_roles j ON j.job_role_id=a.job_role_id WHERE a.assessment_id=? AND a.user_id=? AND a.status=\'completed\'');$st->execute([$id,$userId]);$assessment=$st->fetch();if(!$assessment){flash('Assessment not found.','error');redirect('assessment/history.php');}
$st=$pdo->prepare('SELECT ar.*,s.skill_name,s.description FROM assessment_results ar JOIN skills s ON s.skill_id=ar.skill_id WHERE ar.assessment_id=? ORDER BY ar.gap_level DESC,s.skill_name');$st->execute([$id]);$results=$st->fetchAll();$gaps=count(array_filter($results,fn($r)=>(int)$r['gap_level']>0));$st=$pdo->prepare('SELECT roadmap_id FROM roadmaps WHERE assessment_id=? AND user_id=? LIMIT 1');$st->execute([$id,$userId]);$existingRoadmap=(int)$st->fetchColumn();$quizStmt=$pdo->prepare('SELECT COUNT(*) answered,SUM(is_correct=1) correct FROM assessment_answers WHERE assessment_id=?');$quizStmt->execute([$id]);$quizSummary=$quizStmt->fetch();
$pageTitle='Assessment results';$active='dashboard';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Your assessment report</span><h1 class="h1">Your skill gap snapshot</h1><p><?=h($assessment['role_name'])?> · Completed <?=date('d M Y',strtotime($assessment['completed_at']))?></p></div><a class="btn btn-outline" href="<?=h(url('assessment/history.php'))?>">Assessment history</a></div>
<section class="result-hero"><div class="result-circle" style="--score:<?=max(0,min(100,(float)$assessment['readiness_score']))?>%"><strong><?=number_format((float)$assessment['readiness_score'],1)?>%</strong></div><div><span class="pill" style="background:#ffffff20;color:#fff">Self-assessed skill coverage</span><h2 style="margin-top:12px">A starting point, not a final verdict.</h2><p>Your selected levels cover <?=count($results)?> role skills. <?= $gaps ?> skill<?= $gaps===1?'':'s' ?> currently sit below the example target levels. Practice and evidence can help you track progress.</p></div></section>
<div class="grid grid-2" style="margin-top:20px;align-items:start"><section class="card card-pad"><div class="panel-title"><h3>Skill-by-skill breakdown</h3><span class="pill pill-blue"><?=count($results)?> mapped skills</span></div><?php foreach($results as $r):?><div class="result-row"><div><strong><?=h($r['skill_name'])?></strong><small><?=h(level_label((int)$r['current_level']))?> · target <?=h(level_label((int)$r['required_level']))?></small></div><div class="result-track"><span style="width:<?=min(100,(float)$r['coverage_percent'])?>%"></span></div><div style="text-align:right"><strong style="font-size:12px"><?=number_format((float)$r['coverage_percent'],0)?>%</strong><small><?=((int)$r['gap_level']>0?'Gap '.$r['gap_level']:'On target')?></small></div></div><?php endforeach;?></section><aside class="stack"><?php if((int)$quizSummary['answered']>0):?><section class="card card-pad"><h3 class="h3">Optional knowledge check</h3><div class="stat-value" style="font-size:25px"><?= (int)$quizSummary['correct'] ?> / <?= (int)$quizSummary['answered'] ?></div><p class="muted small">Correct answers. This knowledge check is displayed separately and is not included in your self-assessed skill coverage score.</p></section><?php endif;?><section class="card card-pad"><h3 class="h3">Your next step</h3><p class="muted small">Generate a roadmap that turns the skills below target into learning and project tasks.</p><?php if($existingRoadmap):?><a class="btn btn-primary btn-block" href="<?=h(url('roadmap/index.php?id='.$existingRoadmap))?>">Open my roadmap →</a><?php else:?><form method="post" action="<?=h(url('roadmap/generate.php'))?>"><?=csrf_field()?><input type="hidden" name="assessment_id" value="<?=$id?>"><button class="btn btn-primary btn-block">Generate my roadmap →</button></form><?php endif;?></section><section class="card card-pad"><h3 class="h3">How to read this score</h3><p class="muted small">The weighted coverage score caps each skill at 100% of its required level. A higher score means your self-assessed levels are closer to the role's configured targets. It does not predict hiring outcomes.</p><a class="link-arrow" href="<?=h(url('careers/view.php?id='.(int)$assessment['job_role_id']))?>">Review role requirements →</a></section></aside></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
